"""모델 관리, 오류 대화상자, 엔진 상태 문구."""

_LANGS = ("ko", "en", "ja", "zh", "es", "fr", "de", "pt", "ru", "it", "vi", "th", "id", "ar", "hi")


def _row(key, values):
    if len(values) != len(_LANGS):
        raise ValueError(f"{key} has {len(values)} languages")
    return (key, *values)


def _same(key, text):
    return _row(key, (text,) * len(_LANGS))


